package org.apache.commons.lang3.math;

import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import org.apache.commons.lang3.StringUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class NumberUtils_isNumber_TriageGen1Test {





    @Test
    public void testIsNumber_Decimal() {
        assertTrue(NumberUtils.isNumber("123.45"));
        assertTrue(NumberUtils.isNumber(".45"));
        assertTrue(NumberUtils.isNumber("123."));
        assertFalse(NumberUtils.isNumber(".."));
        assertFalse(NumberUtils.isNumber("1.2.3"));
        assertFalse(NumberUtils.isNumber("1e2.3")); // decimal in exponent not allowed
    }










}

package org.apache.commons.lang3.math;

import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import org.apache.commons.lang3.StringUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class NumberUtils_isNumber_TriageGen1Test {







    @Test
    public void testIsNumber_Exponent() {
        assertTrue(NumberUtils.isNumber("1e10"));
        assertTrue(NumberUtils.isNumber("1E10"));
        assertTrue(NumberUtils.isNumber("1e+10"));
        assertTrue(NumberUtils.isNumber("1e-10"));
        assertTrue(NumberUtils.isNumber("-1e10"));
        assertFalse(NumberUtils.isNumber("e10")); // no digit before E
        assertFalse(NumberUtils.isNumber("1e")); // trailing E
        assertFalse(NumberUtils.isNumber("1e+")); // trailing sign after E
        assertFalse(NumberUtils.isNumber("1e1e1")); // two E's
    }








}

package org.apache.commons.lang3.math;

import java.io.*;
