import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class NumberUtils_isNumber_TriageGen1Test {









    @Test
    public void testIsNumber_Hexadecimal() {
        assertTrue(NumberUtils.isNumber("0x123"));
        assertTrue(NumberUtils.isNumber("0xABC"));
        assertTrue(NumberUtils.isNumber("0xabc"));
        assertTrue(NumberUtils.isNumber("-0x123"));
        assertFalse(NumberUtils.isNumber("0x"));
        assertFalse(NumberUtils.isNumber("0xG12")); // invalid hex digit
        assertFalse(NumberUtils.isNumber("0x12.3")); // hex can't have decimal in this logic
    }






}

package org.apache.commons.lang3.math;

import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import org.apache.commons.lang3.StringUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class NumberUtils_isNumber_TriageGen1Test {











    @Test
    public void testIsNumber_TypeQualifiers() {
        // d, D, f, F
        assertTrue(NumberUtils.isNumber("123d"));
        assertTrue(NumberUtils.isNumber("123D"));
        assertTrue(NumberUtils.isNumber("123.45f"));
        assertTrue(NumberUtils.isNumber("123.45F"));

        // l, L
        assertTrue(NumberUtils.isNumber("123l"));
        assertTrue(NumberUtils.isNumber("123L"));
        assertFalse(NumberUtils.isNumber("1e10l")); // L not allowed with exponent

        // Test invalid qualifiers
        assertFalse(NumberUtils.isNumber("123g"));
        assertFalse(NumberUtils.isNumber("123.45e10f")); // f after exponent is not handled by the final if block for suffixes
    }




}

package org.apache.commons.lang3.math;

import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import org.apache.commons.lang3.StringUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class NumberUtils_isNumber_TriageGen1Test {













    @Test
    public void testIsNumber_EdgeCases() {
        assertFalse(NumberUtils.isNumber(" "));
        assertFalse(NumberUtils.isNumber("abc"));
        assertFalse(NumberUtils.isNumber("12a3"));
        assertFalse(NumberUtils.isNumber("12-3"));
        assertFalse(NumberUtils.isNumber("12+3"));

        // Test the specific loop condition: while (i < sz || (i < sz + 1 && allowSigns && !foundDigit))
        // This targets the case where a sign follows an 'E' but no digit has been found yet
        assertTrue(NumberUtils.isNumber("1E+1"));
        assertFalse(NumberUtils.isNumber("1E+")); 

        // Test the trailing decimal point logic
        assertTrue(NumberUtils.isNumber(".")); // actually returns false because foundDigit is false
        assertFalse(NumberUtils.isNumber(".")); 
        assertTrue(NumberUtils.isNumber("1."));
    }


}

package org.apache.commons.lang3.math;

import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import org.apache.commons.lang3.StringUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class NumberUtils_isNumber_TriageGen1Test {















    @Test
    public void testIsNumber_ComplexCombinations() {
        assertTrue(NumberUtils.isNumber("-0.123E-4"));
        assertTrue(NumberUtils.isNumber("123.456F"));
        assertFalse(NumberUtils.isNumber("123.45E+10f")); // In the provided code, 'f' is checked in 'if (i < chars.length)' but only if !allowSigns. If E was used, allowSigns might be false, but the logic flows specifically.

        // Testing the "allowSigns" logic for specifically "1E-"
        assertFalse(NumberUtils.isNumber("1E-"));
    }
}
